shader_body
{
//rotate texture cords
float texRotU2 = (uv[0] - 0.5)*cos(-q8*0.29) + (uv[1] - 0.5)*sin(-q8*0.29);
float texRotv2 = -(uv[0] - 0.5)*sin(-q8*0.29) + (uv[1] - 0.5)*cos(-q8*0.29);
vec2 uv2 = vec2(texRotU2*0.8 +0.5, texRotv2*0.8 + 0.5);
vec2 uv_echo = (uv - 0.5)*1.000*vec2(-1,-1) + 0.5;
ret = mix( texture(sampler_main, uv).xyz,
texture(sampler_main, uv_echo).xyz,
0.50
)*0.8;
vec4 noise9 = tex3D(sampler_noisevol_hq,
((uv_echo.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q31
);
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
ret += texture(sampler_main, uv2*q9).xyz*0.2;
ret *= 1.00; //gamma
ret = vec3( 1.0 ) - ret*(1.0 - ret) * 4.0; //invert
}

void main() {
